function render() {
    // clear canvas
    ctx.clearRect(0, 0, W, H);
    // draw gradient neon background
    const bgGrad = ctx.createLinearGradient(0, 0, 0, H);
    bgGrad.addColorStop(0, '#001');
    bgGrad.addColorStop(0.5, '#002');
    bgGrad.addColorStop(1, '#001');
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, W, H);
    // moving tunnel lines
    for (let i = 0; i < 30; i++) {
      const lineX = (i * 40 + (performance.now() / 5)) % W;
      ctx.strokeStyle = 'rgba(0,255,255,0.1)';
      ctx.beginPath();
      ctx.moveTo(lineX, 0);
      ctx.lineTo(lineX, H);
      ctx.stroke();
    }
    // player
    drawNeon(player.x, player.y, PLAYER_SIZE, PLAYER_SIZE, '#0ff');
    // obstacles
    obstacles.forEach(o => drawNeon(o.x, o.y, o.w, o.h, '#f0f'));
    // score
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + Math.floor(score), 10, 20);
    if (!running) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, W, H);
      ctx.fillStyle = '#f88';
      ctx.font = '30px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Game Over', W / 2, H / 2);
    }

